const entradas = $input.all();
if (entradas.length !== 1) throw new Error('Este workflow recebe um evento por execução; configure o chamador no modo each.');
const e = entradas[0].json;
if (e.evento?.tipo !== 'analise_concluida') return [{json:{...e,trello:{status:'evento_ignorado',motivo:'Somente analise_concluida gera sugestão no Kanban.'}}}];
const configuracao = {
  "quadro_id": ($env.APROVA_TRELLO_QUADRO_ID || ''),
  "quadro_nome": ($env.APROVA_TRELLO_QUADRO_NOME || 'Quadro da equipe'),
  "listas": {
    "backlog": {
      "id": ($env.APROVA_TRELLO_LISTA_BACKLOG_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_BACKLOG_NOME || 'Backlog')
    },
    "design": {
      "id": ($env.APROVA_TRELLO_LISTA_DESIGN_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_DESIGN_NOME || 'Design')
    },
    "a_fazer": {
      "id": ($env.APROVA_TRELLO_LISTA_A_FAZER_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_A_FAZER_NOME || 'A Fazer')
    },
    "em_andamento": {
      "id": ($env.APROVA_TRELLO_LISTA_EM_ANDAMENTO_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_EM_ANDAMENTO_NOME || 'Em andamento')
    },
    "revisao": {
      "id": ($env.APROVA_TRELLO_LISTA_REVISAO_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_REVISAO_NOME || 'Revisão de código')
    },
    "teste": {
      "id": ($env.APROVA_TRELLO_LISTA_TESTE_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_TESTE_NOME || 'Fase de teste')
    },
    "concluido": {
      "id": ($env.APROVA_TRELLO_LISTA_CONCLUIDO_ID || ''),
      "nome": ($env.APROVA_TRELLO_LISTA_CONCLUIDO_NOME || 'Concluído')
    }
  }
};
const idsConfigurados = [configuracao.quadro_id, ...Object.values(configuracao.listas).map(lista=>lista.id)];
if (!idsConfigurados.every(id=>/^[0-9a-f]{24}$/i.test(id))) throw new Error('Configure o ID do quadro e das sete listas nas variáveis APROVA_TRELLO_* antes de publicar.');
const erros = [];
if (e.meta?.origem_verificada !== true) erros.push('Evento sem origem verificada pelo Core.');
if (!Number.isSafeInteger(e.meta?.tenant_id) || e.meta.tenant_id <= 0) erros.push('tenant_id inválido.');
if (typeof e.meta?.id_evento !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(e.meta.id_evento)) erros.push('id_evento inválido.');
const m = /^https:\/\/github\.com\/([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)\/pull\/([1-9]\d*)\/?(?:[?#].*)?$/i.exec(e.pr?.url || '');
if (!m || !Number.isSafeInteger(e.pr?.numero) || Number(m[3]) !== e.pr.numero || (m[1]+'/'+m[2]).toLowerCase() !== String(e.repositorio?.full_name || '').toLowerCase()) erros.push('URL da PR, número e repositório inconsistentes.');
if (!['BAIXO','MEDIO','ALTO'].includes(e.risco?.nivel)) erros.push('Nível de risco ausente ou desconhecido; deve vir do núcleo.');
if (erros.length) throw new Error(erros.join(' '));
return [{json:{...e,trello:{status:'pesquisar',quadro_id:configuracao.quadro_id,quadro_nome:configuracao.quadro_nome,lista_revisao_id:configuracao.listas.revisao.id,lista_revisao_nome:configuracao.listas.revisao.nome,configuracao,url_pr:'https://github.com/'+m[1]+'/'+m[2]+'/pull/'+m[3],marcador:'[aPRova:evento:'+e.meta.tenant_id+':'+e.meta.id_evento+']'}}}];

const contexto = $('02 | Preparar Evento e Quadro').first().json;
const paginas = $input.all().map(i=>i.json);
const cards = new Map();
for (const pagina of paginas) {
  if (pagina.statusCode !== 200 || !Array.isArray(pagina.body?.cards)) throw new Error('Falha ou resposta inválida na busca do Trello. Nenhum comentário enviado.');
  for (const card of pagina.body.cards) {
    if (!card || typeof card.id !== 'string') throw new Error('Card inválido na resposta do Trello.');
    cards.set(card.id,card);
  }
}
if (!paginas.length || paginas[paginas.length-1].body.cards.length >= 100) throw new Error('Busca incompleta: limite de páginas atingido. Nenhum comentário enviado.');
const alvo = contexto.trello.url_pr.toLowerCase();
const possuiLink = desc => typeof desc === 'string' && (desc.match(/https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/pull\/[1-9]\d*(?![A-Za-z0-9_-])/gi) || []).some(url=>url.toLowerCase()===alvo);
const encontrados = [...cards.values()].filter(c=>c.idBoard===contexto.trello.quadro_id && c.closed===false && possuiLink(c.desc));
const status = encontrados.length===1 ? 'card_encontrado' : encontrados.length===0 ? 'sem_card_vinculado' : 'vinculo_ambiguo';
return [{json:{...contexto,trello:{...contexto.trello,status,candidatos_busca:cards.size,correspondencias:encontrados.length,cards_correspondentes:encontrados.map(c=>({id:c.id,nome:c.name,url:c.url})),card:encontrados.length===1?encontrados[0]:null}}}];

const contexto = $('05 | Validar Vínculo Único').first().json;
const card = $json.body;
if ($json.statusCode !== 200 || !card || typeof card.id !== 'string') throw new Error('Não foi possível reler o card do Trello.');
const links = typeof card.desc==='string' ? card.desc.match(/https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/pull\/[1-9]\d*(?![A-Za-z0-9_-])/gi)||[] : [];
const valido=card.id===contexto.trello.card.id && card.idBoard===contexto.trello.quadro_id && card.closed===false && links.some(u=>u.toLowerCase()===contexto.trello.url_pr.toLowerCase());
return {json:{...contexto,trello:{...contexto.trello,status:valido?'vinculo_confirmado':'vinculo_alterado',card}}};

const contexto = $('08 | Revalidar Card Atual').first().json;
const paginas=$input.all().map(i=>i.json);
const comentarios=[];
for (const pagina of paginas) {
  if(pagina.statusCode!==200 || !Array.isArray(pagina.body)) throw new Error('Não foi possível conferir os comentários anteriores.');
  for(const acao of pagina.body) {
    if(acao.type!=='commentCard' || typeof acao.data?.text!=='string') throw new Error('Histórico de comentários inválido.');
    comentarios.push(acao);
  }
}
if(!paginas.length || paginas[paginas.length-1].body.length>=1000) throw new Error('Histórico incompleto: limite de páginas atingido. Nenhum comentário enviado.');
const anterior=comentarios.find(a=>a.data.text.includes(contexto.trello.marcador));
if(anterior) return [{json:{...contexto,trello:{...contexto.trello,status:'evento_ja_comentado',comentario_id:anterior.id}}}];
const card=contexto.trello.card;
const listas=Object.fromEntries(Object.values(contexto.trello.configuracao.listas).map(lista=>[lista.id,lista.nome]));
let sugestao;
if(card.idList===contexto.trello.lista_revisao_id) sugestao='O card já está em Revisão de código. Sugestão: mantenham essa etapa até concluir a revisão humana; depois, avaliem manualmente a passagem para Fase de teste.';
else if([contexto.trello.configuracao.listas.teste.id,contexto.trello.configuracao.listas.concluido.id].includes(card.idList)) sugestao='O card já está em uma etapa posterior à revisão. Sugestão: confiram se a etapa atual continua adequada diante desta análise e decidam manualmente se alguma movimentação é necessária.';
else sugestao='Sugestão: se a implementação estiver pronta, avaliem mover este card para Revisão de código, para avaliação humana da PR.';
const texto=v=>String(v??'').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'').trim();
const partes=['aPRova — análise concluída','PR: '+contexto.repositorio.full_name+' #'+contexto.pr.numero,contexto.trello.url_pr,'Autor da PR: '+texto(contexto.pr.autor?.login||contexto.dados?.autor_pr||'não informado'),'Risco informado pelo núcleo: '+contexto.risco.nivel,'Etapa atual: '+(listas[card.idList]||card.idList)];
const motivos=Array.isArray(contexto.risco.motivos)?contexto.risco.motivos:[];
if(motivos.length) partes.push('Motivos:\n'+motivos.slice(0,20).map(m=>'- '+texto(m.descricao||m.nome).slice(0,700)).join('\n'));
if(contexto.risco.explicacao) partes.push('Análise do núcleo: '+texto(contexto.risco.explicacao).slice(0,4000));
partes.push(sugestao,'A análise não comprova aprovação, merge ou conclusão da tarefa. A decisão e a movimentação do card cabem ao time.',contexto.trello.marcador);
return [{json:{...contexto,trello:{...contexto.trello,status:'pronto_para_comentar',lista_anterior:card.idList,comentario:partes.join('\n\n')}}}];

const contexto=$('11 | Conferir Duplicidade e Preparar Comentário').first().json;
if(typeof $json.id!=='string' || $json.type!=='commentCard' || $json.data?.card?.id!==contexto.trello.card.id || $json.data?.text!==contexto.trello.comentario) throw new Error('O Trello não confirmou o comentário esperado. Confira a execução antes de reenviar.');
return {json:{...contexto,trello:{...contexto.trello,status:'comentario_adicionado',comentario_id:$json.id,comentario_em:$json.date}}};

if ($json.trello?.status !== 'comentario_adicionado' || !$json.trello.comentario_id || typeof $json.trello.comentario !== 'string') throw new Error('O Slack só recebe comentários confirmados pelo Trello.');
const texto=$json.trello.comentario;
const pontos=Array.from(texto);
const blocos=[{type:'header',text:{type:'plain_text',text:'Sugestão registrada no Trello',emoji:true}},{type:'section',text:{type:'plain_text',text:('Card: '+String($json.trello.card?.name||'')+'\n'+String($json.trello.card?.url||'')).slice(0,2800),emoji:false}}];
for(let i=0;i<pontos.length;i+=2800) blocos.push({type:'section',text:{type:'plain_text',text:pontos.slice(i,i+2800).join(''),emoji:false}});
if(blocos.length>50) throw new Error('Comentário excede o limite de blocos da mensagem do Slack.');
return {json:{...$json,notificacao_slack:{status:'pendente',comentario_trello_id:$json.trello.comentario_id},slack_payload:{text:('Sugestão registrada no Trello: '+String($json.trello.card?.url||'')+'\n\n'+texto).slice(0,3900),mrkdwn:false,unfurl_links:false,unfurl_media:false,blocks:blocos}}};

const contexto=$('15 | Preparar Aviso do Trello no Slack').item.json;
const resposta=$json.body ?? $json.data;
const enviado=$json.statusCode===200 && typeof resposta==='string' && resposta.trim()==='ok';
return {json:{...contexto,notificacao_slack:{...contexto.notificacao_slack,status:enviado?'enviado':'falha',http_status:Number.isInteger($json.statusCode)?$json.statusCode:null,mensagem:enviado?'Slack confirmou o recebimento.':'O envio ao Slack não foi confirmado. O comentário do Trello continua registrado; confira o nó 16 antes de tentar reenviar somente a notificação.'}}};
